import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import { type Config, readConfig } from './config'
import { endText, notificationArgv } from './notify'
import { book, EMPTY_STATS, formatStats, isStats, type Stats } from './stats'
import { apply, formatClock, HELP, IDLE, isCommandName, isTimer, label, type Timer, type TimerEvent, tick } from './timer'

const hud = atom({ plugin: 'pomodoro', key: 'hud' } as const, '')

async function loadTimer($: EngineInterface): Promise<Timer> {
  const raw = await $.store.get('timer')
  if (raw === undefined) return IDLE
  if (isTimer(raw)) return raw
  await $.store.set('timer', IDLE)
  $.ui.toast('🍅 Pomodoro state reset')
  return IDLE
}

async function loadStats($: EngineInterface): Promise<Stats> {
  const raw = await $.store.get('stats')
  return isStats(raw) ? raw : EMPTY_STATS
}

// The OS banner goes out once, from the session that advanced the store.
function notifyOs($: EngineInterface, cfg: Config, ev: TimerEvent) {
  const body = endText(ev)
  if (!cfg.notify) return
  const sound = ev.kind === 'focusEnded' ? cfg.focusEndSound : cfg.breakEndSound
  $.process
    .run(notificationArgv(body, sound), { timeoutMs: 5000 })
    .catch(err => $.ui.log(`notification failed: ${String(err)}`, { to: 'debug' }))
}

// A store that cannot be read must not crash the worker once a second.
function logFailure($: EngineInterface, err: unknown) {
  $.ui.log(`tick failed: ${String(err)}`, { to: 'debug' })
}

// What this session last saw; lets every session toast a phase end, whoever advanced the store.
type View = { seen: Timer | null }

// One tick: advance the shared timer; one session books and sends the banner, every session toasts.
async function step($: EngineInterface, cfg: Config, view: View): Promise<Timer> {
  const now = await $.clock.now()
  const before = await loadTimer($)
  const { timer, events } = tick(before, now, cfg.autoBreak)
  let truth = timer
  if (events.length > 0) {
    const fresh = await loadTimer($)
    // ponytail: read-compare-write without CAS; two sessions in the same ms can both announce
    if (fresh.phase === before.phase && fresh.endsAt === before.endsAt) {
      await $.store.set('timer', timer)
      let stats = await loadStats($)
      for (const ev of events) if (ev.kind === 'focusEnded') stats = book(stats, ev)
      await $.store.set('stats', stats)
      const last = events[events.length - 1]
      if (last) notifyOs($, cfg, last)
    } else {
      truth = tick(fresh, now, cfg.autoBreak).timer
    }
  }
  const seen = view.seen
  if (seen) {
    const mine = tick(seen, now, cfg.autoBreak)
    const last = mine.events[mine.events.length - 1]
    if (last && truth.seriesId === seen.seriesId && truth.phase === mine.timer.phase) $.ui.toast(`🍅 ${endText(last)}`)
  }
  view.seen = truth
  await update($, hud, () => label(truth, now))
  return truth
}

export const register: Register = (on, options) => {
  const cfg = readConfig(options)
  const view: View = { seen: null }

  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'pomodoro',
      description: 'Pomodoro timer shared across sessions',
      argumentHint: '[start|next|pause|resume|stop|stats] [focus] [break]',
    })
    let isBusy = false
    $.clock.every(1000, () => {
      if (isBusy) return
      isBusy = true
      void step($, cfg, view)
        .catch(err => logFailure($, err))
        .finally(() => {
          isBusy = false
        })
    })
    await step($, cfg, view).catch(err => logFailure($, err))
    return next(e)
  })

  on('command.run', { command: 'pomodoro' }, async ($, e) => {
    const [sub = '', ...args] = e.args.trim().split(/\s+/).filter(Boolean)
    const t = await step($, cfg, view)
    const now = await $.clock.now()
    if (sub === '' || sub === 'status') return { text: `${label(t, now) || 'No pomodoro running.'}\n${HELP}` }
    if (sub === 'stats') return { text: formatStats(await loadStats($), now) }
    if (!isCommandName(sub)) return { text: `Unknown command "${sub}". ${HELP}` }
    const { timer, text } = apply(t, sub, args, now, cfg.defaults)
    if (timer !== t) {
      view.seen = timer
      await $.store.set('timer', timer)
      await update($, hud, () => label(timer, now))
    }
    return { text }
  })

  on('ui.render', { component: 'SessionMode' }, async ($, e, next) => {
    const text = await read($, hud)
    return text ? next({ ...e, props: { ...e.props, modes: [...e.props.modes, text] } }) : next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    // Only what a person typed is gated; task notices, /loop triggers, peers and -p runs pass.
    const isTyped = e.origin.kind === 'composer' || e.origin.kind === 'bridge'
    const text = e.text.trimStart()
    if (!isTyped || text.startsWith('/') || text.startsWith('!')) return next(e)
    const hasPrefix = text.startsWith(cfg.bypassPrefix)
    const rest = hasPrefix ? text.slice(cfg.bypassPrefix.length).trimStart() : e.text
    if (hasPrefix && rest === '') return { drop: `Nothing to send after ${cfg.bypassPrefix}.` }
    const now = await $.clock.now()
    const t = tick(await loadTimer($), now, cfg.autoBreak).timer
    if (t.phase !== 'break' || hasPrefix || cfg.breakPrompts === 'allow') return next({ ...e, text: rest })
    const left = formatClock((t.endsAt ?? now) - now)
    if (cfg.breakPrompts === 'warn') {
      $.ui.toast(`🍅 On break, ${left} left`)
      return next(e)
    }
    return { drop: `🍅 On break (${left} left). Prefix with ${cfg.bypassPrefix} to send anyway.` }
  })
}

