import type { TimerEvent } from './timer'

export const SOUNDS = [
  'Basso', 'Blow', 'Bottle', 'Frog', 'Funk', 'Glass', 'Hero',
  'Morse', 'Ping', 'Pop', 'Purr', 'Sosumi', 'Submarine', 'Tink',
] as const
export const TITLE = '🍅 Pomodoro'

const quote = (s: string) => `"${s.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`

export function notificationArgv(body: string, sound: string): string[] {
  const withSound = (SOUNDS as readonly string[]).includes(sound) ? ` sound name ${quote(sound)}` : ''
  return ['osascript', '-e', `display notification ${quote(body)} with title ${quote(TITLE)}${withSound}`]
}

export function endText(ev: TimerEvent): string {
  if (ev.kind === 'breakEnded') return 'Break over. Run /pomodoro next.'
  return ev.startsBreak ? `Focus done. Take a ${ev.breakMin} min break.` : 'Focus done. Run /pomodoro next to start your break.'
}

