export type Day = { pomodoros: number; focusMin: number; series: number }
export type Stats = { days: Record<string, Day>; totalPomodoros: number; totalSeries: number; longestSeries: number }

export const EMPTY_STATS: Stats = { days: {}, totalPomodoros: 0, totalSeries: 0, longestSeries: 0 }
const KEEP_DAYS = 365
const NO_DAY: Day = { pomodoros: 0, focusMin: 0, series: 0 }

const pad = (n: number) => String(n).padStart(2, '0')

export function dateKey(ms: number): string {
  const d = new Date(ms)
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

// Calendar arithmetic, not ms arithmetic, so DST days stay one day long.
function daysBefore(ms: number, n: number): string {
  const d = new Date(ms)
  return dateKey(new Date(d.getFullYear(), d.getMonth(), d.getDate() - n).getTime())
}

export function book(s: Stats, ev: { at: number; seriesCount: number; focusMin: number }): Stats {
  const key = dateKey(ev.at)
  const day = s.days[key] ?? NO_DAY
  const isNewSeries = ev.seriesCount === 1 ? 1 : 0
  const cutoff = daysBefore(ev.at, KEEP_DAYS)
  const days = Object.fromEntries(
    Object.entries({
      ...s.days,
      [key]: { pomodoros: day.pomodoros + 1, focusMin: day.focusMin + ev.focusMin, series: day.series + isNewSeries },
    }).filter(([k]) => k >= cutoff),
  )
  return {
    days,
    totalPomodoros: s.totalPomodoros + 1,
    totalSeries: s.totalSeries + isNewSeries,
    longestSeries: Math.max(s.longestSeries, ev.seriesCount),
  }
}

export function isStats(x: unknown): x is Stats {
  if (typeof x !== 'object' || x === null) return false
  const s = x as Record<string, unknown>
  return (
    typeof s.days === 'object' && s.days !== null && !Array.isArray(s.days) &&
    typeof s.totalPomodoros === 'number' &&
    typeof s.totalSeries === 'number' &&
    typeof s.longestSeries === 'number'
  )
}

const pomodoros = (n: number) => `${n} pomodoro${n === 1 ? '' : 's'}`

export function formatStats(s: Stats, now: number): string {
  const today = s.days[dateKey(now)] ?? NO_DAY
  const sinceMonday = (new Date(now).getDay() + 6) % 7
  let weekPomodoros = 0
  let weekMinutes = 0
  for (let i = 0; i <= sinceMonday; i++) {
    const d = s.days[daysBefore(now, i)]
    if (d) {
      weekPomodoros += d.pomodoros
      weekMinutes += d.focusMin
    }
  }
  return [
    `Today:      ${pomodoros(today.pomodoros)}, ${today.focusMin} min focus, ${today.series} series`,
    `This week:  ${pomodoros(weekPomodoros)}, ${weekMinutes} min focus`,
    `All time:   ${pomodoros(s.totalPomodoros)}, longest series ${s.longestSeries}`,
  ].join('\n')
}

