export type Phase = 'idle' | 'focus' | 'done' | 'break' | 'ready' | 'paused'
type Running = 'focus' | 'break'

export type Timer = {
  phase: Phase
  endsAt: number | null
  pausedPhase: Running | null
  remainingMs: number | null
  seriesId: number | null
  seriesCount: number
  focusMin: number
  breakMin: number
}

export type Durations = { focusMin: number; breakMin: number }

export type TimerEvent =
  | { kind: 'focusEnded'; at: number; seriesCount: number; focusMin: number; breakMin: number; startsBreak: boolean }
  | { kind: 'breakEnded'; at: number }

export type CommandName = 'start' | 'next' | 'pause' | 'resume' | 'stop'

export const MINUTE = 60_000
const MAX_FOCUS = 180
const MAX_BREAK = 60
const PHASES: readonly string[] = ['idle', 'focus', 'done', 'break', 'ready', 'paused']
const COMMANDS: readonly string[] = ['start', 'next', 'pause', 'resume', 'stop']

export const IDLE: Timer = {
  phase: 'idle',
  endsAt: null,
  pausedPhase: null,
  remainingMs: null,
  seriesId: null,
  seriesCount: 0,
  focusMin: 25,
  breakMin: 5,
}

export const HELP =
  'Commands: /pomodoro start [focus] [break], next [focus] [break], pause, resume, stop, stats'

const EXAMPLE = 'Example: /pomodoro start 50 10'

function toMinutes(raw: string, max: number): number | null {
  if (!/^\d+$/.test(raw)) return null
  const n = Number(raw)
  return n >= 1 && n <= max ? n : null
}

export function parseDurations(args: readonly string[], base: Durations): Durations | { error: string } {
  if (args.length > 2) return { error: `Too many values. ${EXAMPLE}` }
  const [focus, brk] = args
  const focusMin = focus === undefined ? base.focusMin : toMinutes(focus, MAX_FOCUS)
  if (focusMin === null) return { error: `Focus must be a whole number of minutes from 1 to ${MAX_FOCUS}. ${EXAMPLE}` }
  const breakMin = brk === undefined ? base.breakMin : toMinutes(brk, MAX_BREAK)
  if (breakMin === null) return { error: `Break must be a whole number of minutes from 1 to ${MAX_BREAK}. ${EXAMPLE}` }
  return { focusMin, breakMin }
}

export function formatClock(ms: number): string {
  const s = Math.max(0, Math.ceil(ms / 1000))
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`
}

export function label(t: Timer, now: number): string {
  switch (t.phase) {
    case 'idle':
      return ''
    case 'focus':
    case 'break':
      return `🍅 ${t.phase} ${formatClock((t.endsAt ?? now) - now)}`
    case 'done':
      return '🍅 done (next)'
    case 'ready':
      return '🍅 ready (next)'
    case 'paused':
      return `🍅 paused ${formatClock(t.remainingMs ?? 0)}`
  }
}

export function isCommandName(s: string): s is CommandName {
  return COMMANDS.includes(s)
}

export function isTimer(x: unknown): x is Timer {
  if (typeof x !== 'object' || x === null) return false
  const t = x as Record<string, unknown>
  const numOrNull = (v: unknown) => v === null || typeof v === 'number'
  return (
    PHASES.includes(t.phase as string) &&
    numOrNull(t.endsAt) &&
    numOrNull(t.remainingMs) &&
    numOrNull(t.seriesId) &&
    (t.pausedPhase === null || t.pausedPhase === 'focus' || t.pausedPhase === 'break') &&
    typeof t.seriesCount === 'number' &&
    typeof t.focusMin === 'number' &&
    typeof t.breakMin === 'number'
  )
}

export function apply(
  t: Timer,
  name: CommandName,
  args: readonly string[],
  now: number,
  defaults: Durations,
): { timer: Timer; text: string } {
  const refuse = (text: string) => ({ timer: t, text })
  switch (name) {
    case 'start': {
      const d = parseDurations(args, defaults)
      if ('error' in d) return refuse(d.error)
      return {
        timer: { ...IDLE, ...d, phase: 'focus', endsAt: now + d.focusMin * MINUTE, seriesId: now },
        text: `🍅 Focus for ${d.focusMin} min, then a ${d.breakMin} min break.`,
      }
    }
    case 'next': {
      if (t.phase === 'idle') return refuse('No active series. Use /pomodoro start.')
      if (t.phase === 'paused') return refuse('Paused. Use /pomodoro resume first.')
      if (t.phase === 'focus') return refuse('Focus is still running. Use /pomodoro stop to end the series.')
      const d = parseDurations(args, t)
      if ('error' in d) return refuse(d.error)
      if (t.phase === 'done') {
        return {
          timer: { ...t, ...d, phase: 'break', endsAt: now + d.breakMin * MINUTE },
          text: `🍅 Break for ${d.breakMin} min.`,
        }
      }
      return {
        timer: { ...t, ...d, phase: 'focus', endsAt: now + d.focusMin * MINUTE },
        text: `🍅 Focus for ${d.focusMin} min (pomodoro ${t.seriesCount + 1} of this series).`,
      }
    }
    case 'pause': {
      if (t.phase !== 'focus' && t.phase !== 'break') return refuse('Nothing to pause.')
      const remainingMs = Math.max(0, (t.endsAt ?? now) - now)
      return {
        timer: { ...t, phase: 'paused', pausedPhase: t.phase, remainingMs, endsAt: null },
        text: `🍅 Paused with ${formatClock(remainingMs)} left. Use /pomodoro resume.`,
      }
    }
    case 'resume': {
      if (t.phase !== 'paused' || t.pausedPhase === null) return refuse('Nothing to resume. Use /pomodoro start.')
      const left = t.remainingMs ?? 0
      return {
        timer: { ...t, phase: t.pausedPhase, endsAt: now + left, pausedPhase: null, remainingMs: null },
        text: `🍅 Resumed ${t.pausedPhase}, ${formatClock(left)} left.`,
      }
    }
    case 'stop': {
      if (t.phase === 'idle') return refuse('Nothing to stop.')
      return { timer: { ...IDLE, focusMin: t.focusMin, breakMin: t.breakMin }, text: '🍅 Stopped. Series ended.' }
    }
  }
}

// autoBreak off: a finished focus waits in 'done' until /pomodoro next starts the break.
export function tick(t: Timer, now: number, autoBreak: boolean): { timer: Timer; events: TimerEvent[] } {
  const events: TimerEvent[] = []
  let cur = t
  for (;;) {
    if (cur.phase === 'focus' && cur.endsAt !== null && now >= cur.endsAt) {
      const seriesCount = cur.seriesCount + 1
      const ended = { kind: 'focusEnded', at: cur.endsAt, seriesCount, focusMin: cur.focusMin, breakMin: cur.breakMin } as const
      events.push({ ...ended, startsBreak: autoBreak })
      cur = autoBreak
        ? { ...cur, phase: 'break', seriesCount, endsAt: cur.endsAt + cur.breakMin * MINUTE }
        : { ...cur, phase: 'done', seriesCount, endsAt: null }
    } else if (cur.phase === 'break' && cur.endsAt !== null && now >= cur.endsAt) {
      events.push({ kind: 'breakEnded', at: cur.endsAt })
      cur = { ...cur, phase: 'ready', endsAt: null }
    } else {
      return { timer: cur, events }
    }
  }
}

